  entry := logger.Build(c)
  got := entry.GetMessage()
  if !bytes.Equal(got.GetData(), expected) || got.GetLength() != uint32(len(expected)) { t.Errorf("%T logged length=%d data=%x, want length=%d data=%x", c, got.GetLength(), got.GetData(), len(expected), expected) }
 }
}
