)

type reviewLRSStream struct { grpc.ClientStream; interval *durationpb.Duration }
func (s *reviewLRSStream) Send(*lrspb.LoadStatsRequest) error { return nil }
func (s *reviewLRSStream) Recv() (*lrspb.LoadStatsResponse, error) { return &lrspb.LoadStatsResponse{LoadReportingInterval:s.interval},nil }
func TestReviewInvalidIntervalDiagnostics(t *testing.T) {
 for _, interval := range []*durationpb.Duration{nil, {Nanos:1000000000}, {Seconds:1,Nanos:-1}} {
